function validate([widths, s]) {
  if (widths.length !== 26) return 'widths needs exactly 26 values, one per letter.';
  if (widths.some(w => !Number.isInteger(w) || w < 2 || w > 10)) return 'Each width is a whole number from 2 to 10.';
  if (s.length < 1 || s.length > 1000) return 's needs 1 to 1000 letters.';
  if (!/^[a-z]+$/.test(s)) return 's may contain only lowercase letters.';
  return null;
}

