function numberOfLines(widths, s) {
  // Build each line as an actual string, then measure the last one.
  const alphabet = 'abcdefghijklmnopqrstuvwxyz';
  const measure = (text) => [...text].reduce((total, c) => total + widths[alphabet.indexOf(c)], 0);
  const rows = [];
  let start = 0;
  while (start < s.length) {
    let end = start;
    while (end < s.length && measure(s.slice(start, end + 1)) <= 100) end++;
    rows.push(s.slice(start, end));
    start = end;
  }
  return [rows.length, measure(rows[rows.length - 1])];
}

