function generate(rand, size) {
  const mode = rand();
  let widths;
  if (mode < 0.25) {
    const w = 2 + Math.floor(rand() * 9);
    widths = Array(26).fill(w);
  } else if (mode < 0.4) {
    const pool = [2, 4, 5, 10];
    widths = Array.from({ length: 26 }, () => pool[Math.floor(rand() * pool.length)]);
  } else {
    widths = Array.from({ length: 26 }, () => 2 + Math.floor(rand() * 9));
  }
  const n = size === 'large' ? 900 + Math.floor(rand() * 101) : 1 + Math.floor(rand() * 40);
  const letters = rand() < 0.3 ? 3 : 26;
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + Math.floor(rand() * letters));
  return [widths, s];
}
